ep_event_rollup.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let deviceId = str(body.deviceId ?? req.deviceId ?? "").trim();

let events = vdb.collection("device_events");
let rows = [];
if (deviceId != "") {
  let lookup = events.find({deviceId: {$eq: deviceId}}, 500);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = events.find({}, 500);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No device events are available for rollup"};
}

if (deviceId == "") {
  deviceId = str(rows[0].deviceId ?? "").trim();
}

let filtered = [];
for (row : rows) {
  if (str((row ?? {}).deviceId ?? "").trim() == deviceId) {
    filtered.add(row);
  }
}
if (leng(filtered) == 0) {
  return {ok: false, statusCode: 404, reason: "No device events matched the requested deviceId", deviceId: deviceId};
}

let count = 0;
let total = 0;
let minReading = 0;
let maxReading = 0;
let latestTimestamp = "";
for (row : filtered) {
  let reading = row.reading ?? 0;
  if (reading == "") {
    reading = 0;
  }
  if (count == 0) {
    minReading = reading;
    maxReading = reading;
  } else {
    if (reading < minReading) {
      minReading = reading;
    }
    if (reading > maxReading) {
      maxReading = reading;
    }
  }
  total = total + reading;
  count = count + 1;
  let ts = str(row.timestamp ?? "").trim();
  if (latestTimestamp == "" || ts > latestTimestamp) {
    latestTimestamp = ts;
  }
}

let average = count > 0 ? total / count : 0;
let bucket = str(body.bucket ?? req.bucket ?? "latest").trim();
let rollupId = deviceId + "::" + bucket;
let nowTs = datetime.now().isoformat();
let rollupDoc = {
  rollupId: rollupId,
  deviceId: deviceId,
  bucket: bucket,
  count: count,
  minReading: minReading,
  maxReading: maxReading,
  averageReading: average,
  latestTimestamp: latestTimestamp,
  rolledUpAt: nowTs,
  rolledUpBy: actor
};

if (dryRun) {
  return {ok: true, dryRun: true, deviceId: deviceId, count: count, rollup: rollupDoc};
}

let rollups = vdb.collection("device_event_rollups");
let existing = rollups.find({rollupId: {$eq: rollupId}}, 1);
let existingRows = existing.data ?? [];
let saveRes = {};
if (leng(existingRows) > 0) {
  saveRes = rollups.update({rollupId: {$eq: rollupId}}, rollupDoc);
} else {
  saveRes = rollups.insert(rollupDoc);
}
if (saveRes.ok == false) {
  return {ok: false, statusCode: 500, reason: saveRes.error ?? "Failed to persist telemetry rollup", deviceId: deviceId, result: saveRes};
}

return {ok: true, deviceId: deviceId, count: count, minReading: minReading, maxReading: maxReading, averageReading: average, latestTimestamp: latestTimestamp, rollupId: rollupId, rolledUpAt: nowTs};

